using Amazon.S3;
using Amazon.S3.Model;
using Cleanse.Core.Abstractions;

namespace Cleanse.Api.Imports;

/// <summary>
/// CDP provisions the bucket; keys are always generated by the service, so an uploaded filename
/// can never influence the object path.
/// </summary>
public sealed class S3ImportFileStore(IAmazonS3 client, string bucketName) : IImportFileStore
{
    public async Task WriteAsync(string key, Stream content, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(key);
        ArgumentNullException.ThrowIfNull(content);

        await client.PutObjectAsync(
            new PutObjectRequest
            {
                BucketName = bucketName,
                Key = key,
                InputStream = content,
                ContentType = "text/csv"
            },
            cancellationToken);
    }

    public async Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(key);

        var response = await client.GetObjectAsync(bucketName, key, cancellationToken);
        return response.ResponseStream;
    }

    public async Task<bool> ExistsAsync(string key, CancellationToken cancellationToken = default)
    {
        try
        {
            await client.GetObjectMetadataAsync(bucketName, key, cancellationToken);
            return true;
        }
        catch (AmazonS3Exception ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return false;
        }
    }
}
